    fun checkAndUpdateFenceState() {
        val lastLoc = persistentStateManager.getLastLocation() ?: return
        val fix = com.trackmaster.app.core.LocationFix(
            lat = lastLoc.latitude,
            lng = lastLoc.longitude,
